{"file_path":"./","content":"import fs from 'node:fs';
import crypto from 'node:crypto';

const p = String.raw`./`;
let s = fs.readFileSync(p, 'utf8');
if (s.charCodeAt(0) === 0xfeff) s = s.slice(1);
s = s.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
s = s.replace(/\n+$/, '');

// 内容红线自检
const warns = [];
if (s.includes('~')) warns.push('contains halfwidth tilde U+007E');
if (/<br\s*\/?>/i.test(s)) warns.push('contains <br>');
if (/^\|.*\n(?!\|)/m.test(s)) warns.push('possible broken table');

const body = Buffer.from(s, 'utf8');
const sha = crypto.createHash('sha256').update(body).digest('hex');
const line = `EVIDENCE: ${p}|${body.length}|${sha.slice(0, 12)}`;
fs.writeFileSync(p, Buffer.concat([body, Buffer.from('\n\n' + line + '\n', 'utf8')]));

const chk = fs.readFileSync(p);
console.log('BODY_BYTES=' + body.length);
console.log('SHA256=' + sha);
console.log('SHA12=' + sha.slice(0, 12));
console.log('EVIDENCE_LINE=' + line);
console.log('FILE_BYTES=' + chk.length);
console.log('HAS_BOM=' + (chk[0] === 0xef && chk[1] === 0xbb && chk[2] === 0xbf));
console.log('HAS_CR=' + chk.includes(0x0d));
console.log('WARN=' + (warns.length ? warns.join('; ') : 'none'));
console.log('TAIL=' + JSON.stringify(chk.toString('utf8').slice(-100)));
"}

